import type { Op } from '../shared/ops';

/** What the server records. `author` is always the person (or AI) responsible. */
export type AuditEntryInput =
  | {
      kind: 'edit';
      /** The edit as applied to the server's text, in log order. */
      op: Op;
      author: string;
      /** For edits generated by the AI: the person who accepted them. */
      acceptedBy?: string;
    }
  | { kind: 'checkpoint'; checkpointId: string; hash: string; author: string }
  | { kind: 'approval'; checkpointId: string; author: string };

/** A stored entry: the input plus a sequence number and a timestamp added by the log. */
export type AuditEntry = AuditEntryInput & { seq: number; at: number };

/** Append-only store. Entries can't be changed or removed once written. */
export class AuditLog {
  private readonly stored: AuditEntry[] = [];

  /** `now` supplies timestamps, usually the simulated clock. */
  constructor(private readonly now: () => number = () => Date.now()) {}

  append(entry: AuditEntryInput): AuditEntry {
    const stored = deepFreeze({
      ...structuredClone(entry),
      seq: this.stored.length + 1,
      at: this.now(),
    }) as AuditEntry;
    this.stored.push(stored);
    return stored;
  }

  /** All entries, oldest first. */
  entries(): readonly AuditEntry[] {
    return [...this.stored];
  }

  get size(): number {
    return this.stored.length;
  }
}

function deepFreeze<T>(value: T): T {
  if (value && typeof value === 'object') {
    for (const child of Object.values(value)) deepFreeze(child);
    Object.freeze(value);
  }
  return value;
}
